function calculate_encashment_days(frm) {
    if (frm.doc.custom_is_employee_going_on_vacation){
        if (frm.doc.custom_vacation_from && frm.doc.custom_vacation_end) {
            let from = frappe.datetime.str_to_obj(frm.doc.custom_vacation_from);
            let to = frappe.datetime.str_to_obj(frm.doc.custom_vacation_end);

            if (to <= from) {
                frappe.msgprint("Vacation End Date must be greater than Vacation From Date");
                frm.set_value("custom_vacation_end", null);
                frm.set_value("custom_vacation_days", 0);
                frm.set_value("encashment_days", 0);
                return;
            }

            let vacation_days = frappe.datetime.get_diff(to, from) + 1;
            frm.set_value("custom_vacation_days", vacation_days);

        } else {
            frm.set_value("custom_vacation_days", 0);
        }
    }
}

frappe.ui.form.on('Leave Encashment', {
    employee: function(frm) {
        if (frm.doc.employee) {
            frappe.db.get_value('Employee', frm.doc.employee, 'date_of_joining')
                .then(r => {
                    if (r && r.message) {
                        let joining_date = r.message.date_of_joining;
                        console.log("Joining Date:", joining_date);

                        // Set into field
                        frm.set_value('custom_from_date', joining_date);
                    }
                });
        }
    },

    refresh(frm) {
        if (frm.doc.employee) {
            frappe.db.get_value('Employee', frm.doc.employee, 'date_of_joining')
                .then(r => {
                    if (r && r.message) {
                        let joining_date = r.message.date_of_joining;
                        console.log("Joining Date:", joining_date);

                        // Set again in refresh
                        frm.set_value('custom_from_date', joining_date);
                    }
                });
        }
    }
});

frappe.ui.form.on('Leave Encashment', {
    refresh(frm) {
        // your code here
    },
    employee: function(frm) {
        if (frm.doc.employee) {
            frappe.db.get_value('Employee', frm.doc.employee, 'date_of_joining')
                .then(r => {
                    if (r.message) {
                        frm.set_value('custom_from_date', r.message.date_of_joining);
                    }
                });
        }
    },

    // Employee going on vacation checkbox
    custom_is_employee_going_on_vacation: function(frm) {
        if(frm.doc.custom_is_employee_going_on_vacation){
            // Uncheck leaving company if vacation is selected
            frm.set_value("custom_employee_leaving_company", 0);
        } else {
            // Clear vacation-related fields if unchecked
            frm.set_value("custom_vacation_from", null);
            frm.set_value("custom_vacation_end", null);
            frm.set_value("custom_vacation_days", null);
            frm.set_value("custom_forecasted_encashable_days", null);
        }
    },

    // Employee leaving company
    custom_employee_leaving_company: function(frm) {
        if (!frm.doc.custom_employee_leaving_company){
            frm.set_value("custom_forecasted_encashable_days",0);
            return;
        }

        frm.set_value("custom_is_employee_going_on_vacation", 0);

        if (!frm.doc.employee) {
            frappe.msgprint({
                title: __('Employee Missing'),
                indicator: 'red',
                message: __('Please select an Employee first.')
            });
            frm.set_value("custom_employee_leaving_company", 0);
            return;
        }

        // Fetch relieving_date from Employee Master
        frappe.db.get_value("Employee", frm.doc.employee, "relieving_date")
            .then(r => {
                if (!r.message || !r.message.relieving_date) {
                    frappe.msgprint({
                        title: __('Relieving Date Not Found'),
                        indicator: 'red',
                        message: __('Relieving Date is not set in Employee Master for {0}.<br><br>Please update it here: <a href="/app/employee/{1}" target="_blank">{1}</a>',
                            [frm.doc.employee_name || frm.doc.employee, frm.doc.employee]
                        )
                    });
                    frm.set_value("custom_employee_leaving_company", 0);
                    return;
                }

                let relieving_date = r.message.relieving_date;
                frm.set_value("custom_employee_relieving_date", relieving_date);

                let joining_date = frm.doc.custom_from_date;
                let leave_balance = flt(frm.doc.leave_balance);

                if (!joining_date) {
                    frappe.msgprint("Joining Date is missing.");
                    return;
                }

                // Service calculation
                let today = frappe.datetime.get_today();
                let today_date = new Date(today);
                let joining = new Date(joining_date);
                let relieving = new Date(relieving_date);

                let years_of_service = today_date.getFullYear() - joining.getFullYear();
                let month_diff = today_date.getMonth() - joining.getMonth();
                if (month_diff < 0 || (month_diff === 0 && today_date.getDate() < joining.getDate())) {
                    years_of_service--;
                }

                let yearly_leave = years_of_service > 5 ? 30 : 21;

                // First day of current month
                let first_day_of_month = new Date(today_date.getFullYear(), today_date.getMonth(), 1);
                let diff_time = relieving - first_day_of_month;
                let calculated_days = Math.ceil(diff_time / (1000 * 60 * 60 * 24));
                if (calculated_days < 0) calculated_days = 0;

                let forecasting_days = (yearly_leave / 365) * calculated_days;
                let forecasted_days = leave_balance + forecasting_days;

                frm.set_value("custom_forecasted_encashable_days", forecasted_days.toFixed(2));
            });
    },

    // Trigger vacation days and forecasted days when from/to dates change
    custom_vacation_from: function(frm){
        frm.trigger("set_vacation_days");
        frm.trigger("update_forecasted_encashable_days");
    },

    custom_vacation_end: function(frm){
        frm.trigger("set_vacation_days");
        frm.trigger("update_forecasted_encashable_days");
    },

    // Calculate vacation days
    set_vacation_days: function(frm) {
        if (frm.doc.custom_vacation_from && frm.doc.custom_vacation_end) {
            let from_date = new Date(frm.doc.custom_vacation_from);
            let to_date = new Date(frm.doc.custom_vacation_end);

            let diffTime = to_date - from_date;
            let diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24)) + 1;

            frm.set_value("custom_vacation_days", diffDays);
        } else {
            frm.set_value("custom_vacation_days", null);
        }
    },

    // Set encashment days equal to vacation days
    custom_vacation_days: function(frm) {
        frm.set_value('encashment_days', frm.doc.custom_vacation_days);
    },

    // Calculate forecasted encashable days while going on vacation
    update_forecasted_encashable_days: function(frm) {
        if (!frm.doc.custom_is_employee_going_on_vacation || !frm.doc.custom_vacation_from) {
            frm.set_value("custom_forecasted_encashable_days", null);
            return;
        }

        if (!frm.doc.employee) {
            frappe.msgprint({
                title: __('Employee Missing'),
                indicator: 'red',
                message: __('Please select an Employee first.')
            });
            return;
        }

        let vacation_from_date = new Date(frm.doc.custom_vacation_from);

        // Day before vacation
        let calculation_date = new Date(vacation_from_date);
        calculation_date.setDate(calculation_date.getDate() - 1);

        let joining_date = frm.doc.custom_from_date;
        let leave_balance = flt(frm.doc.leave_balance);

        if (!joining_date) {
            frappe.msgprint("Joining Date is missing.");
            return;
        }

        let today = frappe.datetime.get_today();
        let today_date = new Date(today);
        let joining = new Date(joining_date);

        let years_of_service = today_date.getFullYear() - joining.getFullYear();
        let month_diff = today_date.getMonth() - joining.getMonth();
        if (month_diff < 0 || (month_diff === 0 && today_date.getDate() < joining.getDate())) {
            years_of_service--;
        }

        let yearly_leave = years_of_service > 5 ? 30 : 21;

        // First day of current month
        let first_day_of_month = new Date(today_date.getFullYear(), today_date.getMonth(), 1);

        // Days difference from first day of month to day before vacation
        let diff_time = calculation_date - first_day_of_month;
        let calculated_days = Math.ceil(diff_time / (1000 * 60 * 60 * 24));
        if (calculated_days < 0) calculated_days = 0;

        let forecasting_days = (yearly_leave / 365) * calculated_days;
        let forecasted_days = leave_balance + forecasting_days;

        frm.set_value("custom_forecasted_encashable_days", forecasted_days.toFixed(2));
    }
});
